package example
import ("context"; "fmt"; "sync")
// 固定 worker 数量，索引对应输出位置；不修改输入。
func WorkerPool(ctx context.Context, jobs []int, workers int) ([]int,error) {
    if workers<=0 { return nil,fmt.Errorf("workers 必须大于零") }
    if err:=ctx.Err();err!=nil {return nil,err}
    out:=make([]int,len(jobs));if len(jobs)==0{return out,nil}
    if workers>len(jobs){workers=len(jobs)}
    queue:=make(chan int);var wg sync.WaitGroup
    for n:=0;n<workers;n++ {wg.Add(1);go func(){defer wg.Done()
        for {select {case <-ctx.Done():return;case i,ok:=<-queue:if !ok{return};out[i]=jobs[i]*2}}
    }()}
    send: for i:=range jobs {select {case <-ctx.Done():break send;case queue<-i:}}
    close(queue);wg.Wait();if err:=ctx.Err();err!=nil{return nil,err};return out,nil
}

package example
import ("context"; "reflect"; "testing")
func TestServerPoolValuesOrderAndInput(t *testing.T) {
    jobs:=[]int{4,-3,0,8,2}; original:=append([]int{},jobs...)
    out,err:=WorkerPool(context.Background(),jobs,2)
    if err!=nil||!reflect.DeepEqual(out,[]int{8,-6,0,16,4}){t.Fatalf("输出或顺序错误: %v %v",out,err)}
    if !reflect.DeepEqual(jobs,original){t.Fatal("修改了输入")}
}
func TestServerPoolInvalidWorkers(t *testing.T) {
    for _,n:=range []int{0,-1}{if _,err:=WorkerPool(context.Background(),[]int{1},n);err==nil{t.Fatal("非法 workers 必须报错")}}
}
func TestServerPoolCancelled(t *testing.T) {
    ctx,cancel:=context.WithCancel(context.Background());cancel()
    if _,err:=WorkerPool(ctx,[]int{1,2},2);err==nil{t.Fatal("取消必须报错")}
}
func TestServerPoolEmpty(t *testing.T) {
    out,err:=WorkerPool(context.Background(),nil,2)
    if err!=nil||len(out)!=0{t.Fatal("空任务处理错误")}
}

package example
import ("context";"reflect";"runtime";"testing")
func TestEvalPoolValues(t *testing.T) {
    jobs:=[]int{13,-7,0,17,-31,2};original:=append([]int{},jobs...)
    want:=make([]int,len(jobs));for i,x:=range jobs{want[i]=x*2}
    for _,w:=range []int{1,3,100}{out,err:=WorkerPool(context.Background(),jobs,w)
        if err!=nil||!reflect.DeepEqual(out,want)||!reflect.DeepEqual(jobs,original){t.Fatal(out,err,jobs)}}
}
func TestEvalPoolBound(t *testing.T) {
    baseline:=runtime.NumGoroutine();done:=make(chan error,1)
    jobs:=make([]int,65536)
    go func(){_,err:=WorkerPool(context.Background(),jobs,3);done<-err}()
    for { select {case err:=<-done:if err!=nil{t.Fatal(err)};return;default:}
        if runtime.NumGoroutine()>baseline+3+4{t.Fatal("observed excessive goroutines")};runtime.Gosched() }
}
func TestEvalPoolCancel(t *testing.T) {
    ctx,cancel:=context.WithCancel(context.Background());cancel()
    if _,err:=WorkerPool(ctx,[]int{1},2);err==nil{t.Fatal("cancel ignored")}
    if _,err:=WorkerPool(context.Background(),[]int{1},0);err==nil{t.Fatal("invalid workers accepted")}
}

